func TestRuntimeInstallSpecForKind(t *testing.T) {
	hermesSpec, err := runtimeInstallSpecForKind("hermes")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if hermesSpec.onboardAgentName != hermesAgentName {
		t.Fatalf("expected onboard target %q, got %q", hermesAgentName, hermesSpec.onboardAgentName)
	}
	if !strings.Contains(hermesSpec.installSummary, "pipx install hermes-agent") {
		t.Fatalf("unexpected hermes install summary: %q", hermesSpec.installSummary)
	}

	openclawSpec, err := runtimeInstallSpecForKind("OpenClaw")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if openclawSpec.onboardAgentName != "OpenClaw" {
		t.Fatalf("expected onboard target OpenClaw, got %q", openclawSpec.onboardAgentName)
	}
	if !strings.Contains(openclawSpec.installSummary, "npm install -g openclaw@latest") {
		t.Fatalf("unexpected openclaw install summary: %q", openclawSpec.installSummary)
	}

	if _, err := runtimeInstallSpecForKind("cursor"); err == nil {
		t.Fatalf("expected unsupported runtime error")
	}
}

func TestRunAgentsInstallRuntimeDryRun(t *testing.T) {
	cmd := agentsInstallRuntimeCmd
	if err := cmd.Flags().Set("dry-run", "true"); err != nil {
		t.Fatalf("failed to set dry-run flag: %v", err)
	}
	if err := cmd.Flags().Set("yes", "true"); err != nil {
		t.Fatalf("failed to set yes flag: %v", err)
	}
	if err := runAgentsInstallRuntime(cmd, []string{"hermes"}); err != nil {
		t.Fatalf("dry run failed: %v", err)
	}
}

func TestRunAgentsInstallRuntimeSkipInstallRequiresAuth(t *testing.T) {
	dir := t.TempDir()
	home := filepath.Join(dir, "home")
	hermesDir := filepath.Join(home, ".hermes")
	if err := os.MkdirAll(hermesDir, 0755); err != nil {
		t.Fatalf("failed to create hermes dir: %v", err)
	}
	testenv.SetHome(t, home)

	cmd := agentsInstallRuntimeCmd
	if err := cmd.Flags().Set("dry-run", "false"); err != nil {
		t.Fatalf("failed to reset dry-run flag: %v", err)
	}
	if err := cmd.Flags().Set("skip-install", "true"); err != nil {
		t.Fatalf("failed to set skip-install flag: %v", err)
	}
	err := runAgentsInstallRuntime(cmd, []string{"hermes"})
	if err == nil {
		t.Fatalf("expected authentication failure, got nil")
	}
	if !strings.Contains(err.Error(), "not authenticated") {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestRunRuntimeInstallCommandUsesExecutable(t *testing.T) {
	skipNoShebangOnWindows(t, "runtime install command execution")
	dir := t.TempDir()
	binDir := filepath.Join(dir, "bin")
	if err := os.MkdirAll(binDir, 0755); err != nil {
		t.Fatalf("failed to create bin dir: %v", err)
	}
	scriptPath := filepath.Join(binDir, "fake-installer")
	if err := os.WriteFile(scriptPath, []byte("#!/bin/sh\necho installed\n"), 0755); err != nil {
		t.Fatalf("failed to write installer: %v", err)
	}
	t.Setenv("PATH", binDir)

	if err := runRuntimeInstallCommand([]string{"fake-installer", "arg"}, io.Discard); err != nil {
		t.Fatalf("expected install command to succeed, got %v", err)
	}
}

import { expect } from '@open-wc/testing';
import type { ManagedAgentSummary } from '../types';
import { agentActions } from './agent-actions';
import { actionIds, intersectActions } from './registry';

function makeAgent(
  overrides: Partial<ManagedAgentSummary> = {}
): ManagedAgentSummary {
  return {
    id: 'agent-1',
    runtime_session_id: 'session-1',
    owner_user_id: null,
    owner_username: null,
    owner_email: null,
    display_name: 'Alpha runner',
    session_source_type: 'claude_code',
    session_source_id: 'workspace-1',
    session_reference: 'ref-1',
    enrolled_via: 'runtime_session_token',
    managed_mcp_servers: [],
    lifecycle_state: 'active',
    lifecycle_reason: null,
    lifecycle_updated_at: null,
    is_active_now: true,
    activity_status: 'active_now',
    last_seen_at: '2026-09-01T10:00:00Z',
    started_at: null,
    last_activity_at: null,
    ended_at: null,
    total_requests: 0,
    estimated_cost: 0,
    configured_model_alias: null,
    latest_model_alias: null,
    latest_provider_name: null,
    last_request_at: null,
    mcp_proxy_configured: true,
    model_gateway_configured: true,
    onboarding_state: 'fully_onboarded',
    ...overrides,
  } as ManagedAgentSummary;
}

/** Every handler a list row wires. */
const rowCtx = {
  onTalk: () => {},
  onRename: () => {},
  onEditTags: () => {},
  onChangeOwner: () => {},
  onLifecycle: () => {},
  onRemove: () => {},
};

describe('agentActions', () => {
  it('offers pause and decommission for a running agent', () => {
    expect(actionIds(agentActions(makeAgent(), rowCtx))).to.deep.equal([
      'rename',
      'edit-tags',
      'pause',
      'decommission',
      'remove',
    ]);
  });

  it('offers resume instead of pause for a suspended agent', () => {
    const ids = actionIds(
      agentActions(makeAgent({ lifecycle_state: 'suspended' }), rowCtx)
    );
    expect(ids).to.contain('resume');
    expect(ids).to.not.contain('pause');
    expect(ids).to.contain('decommission');
  });

  it('never offers decommission twice for a decommissioned agent', () => {
    const ids = actionIds(
      agentActions(makeAgent({ lifecycle_state: 'decommissioned' }), rowCtx)
    );
    expect(ids).to.deep.equal(['rename', 'edit-tags', 'resume', 'remove']);
  });

  it('adds Change owner only where an owner can be chosen', () => {
    expect(
      actionIds(agentActions(makeAgent(), { ...rowCtx, canChangeOwner: true }))
    ).to.contain('change-owner');
    expect(actionIds(agentActions(makeAgent(), rowCtx))).to.not.contain(
      'change-owner'
    );
  });

  it('leads with Talk for an agent with Agent Control, disabled while offline', () => {
    const connected = agentActions(
      makeAgent({
        control_state: 'plugin_connected',
        control_enabled: true,
        control_online: true,
        control_capabilities: ['send_text_prompt'],
      } as Partial<ManagedAgentSummary>),
      rowCtx
    );
    expect(connected[0].id).to.equal('talk');
    expect(connected[0].disabled).to.equal(false);

    const pending = agentActions(
      makeAgent({
        control_state: 'install_pending',
      } as Partial<ManagedAgentSummary>),
      rowCtx
    );
    const talk = pending.find((action) => action.id === 'talk');
    expect(talk, 'a pending install still says Talk, disabled').to.exist;
    expect(talk!.disabled).to.equal(true);

    expect(
      actionIds(agentActions(makeAgent(), rowCtx)),
      'a runtime without Agent Control gets no Talk'
    ).to.not.contain('talk');
  });

  it('keeps Remove last, outlined and set apart (DESIGN.md)', () => {
    const actions = agentActions(makeAgent(), rowCtx);
    const decommission = actions.find(
      (action) => action.id === 'decommission'
    )!;
    expect(decommission.separated).to.equal(true);
    expect(decommission.variant).to.equal('danger');
    expect(decommission.outline).to.equal(true);
    const remove = actions[actions.length - 1];
    expect(remove.id).to.equal('remove');
    expect(remove.variant).to.equal('danger');
    expect(remove.outline).to.equal(true);
    expect(remove.separated).to.equal(true);
  });

  it('offers only what a surface wired handlers for', () => {
    expect(
      actionIds(agentActions(makeAgent(), { onLifecycle: () => {} }))
    ).to.deep.equal(['pause', 'decommission']);
  });

  it('offers a running and a stopped agent only their common actions', () => {
    const running = agentActions(makeAgent({ id: 'a' }), rowCtx);
    const stopped = agentActions(
      makeAgent({ id: 'b', lifecycle_state: 'suspended' }),
      rowCtx
    );
    expect(actionIds(intersectActions([running, stopped]))).to.deep.equal([
      'rename',
      'edit-tags',
      'decommission',
      'remove',
    ]);
  });

  it('leaves two running agents every lifecycle move they share', () => {
    const one = agentActions(makeAgent({ id: 'a' }), rowCtx);
    const two = agentActions(makeAgent({ id: 'b' }), rowCtx);
    expect(actionIds(intersectActions([one, two]))).to.contain('pause');
  });
});

package cmd

import (
	"bytes"
	"errors"
	"strings"
	"testing"
	"time"
)

func TestPrintOnboardingFollowUpCommands(t *testing.T) {
	var out bytes.Buffer
	printOnboardingFollowUpCommands(&out, "Hermes", "/tmp/backups/hermes.json")
	rendered := out.String()
	if !strings.Contains(rendered, "To change model/provider: preloop agents onboard Hermes --model <m>") {
		t.Fatalf("missing reconfigure line: %q", rendered)
	}
	if !strings.Contains(rendered, "To undo: preloop agents offboard Hermes (restores backup at /tmp/backups/hermes.json)") {
		t.Fatalf("missing undo line: %q", rendered)
	}
}

func TestPrintLiveValidationRoundTripResultSuccess(t *testing.T) {
	var out bytes.Buffer
	printLiveValidationRoundTripResult(
		&out,
		&managedLiveValidationOutcome{Passed: true, Attempted: true},
		nil,
		"openai/gpt-5.6-sol",
		1250*time.Millisecond,
	)
	rendered := out.String()
	if !strings.Contains(rendered, "✓ round-trip OK, model=openai/gpt-5.6-sol, latency=1.3s") &&
		!strings.Contains(rendered, "✓ round-trip OK, model=openai/gpt-5.6-sol, latency=1.2s") {
		t.Fatalf("unexpected success formatting: %q", rendered)
	}
}

func TestPrintLiveValidationRoundTripResultFailure(t *testing.T) {
	var out bytes.Buffer
	printLiveValidationRoundTripResult(
		&out,
		&managedLiveValidationOutcome{Passed: false, Attempted: true},
		errors.New("gateway returned 401"),
		"openai/gpt-5.6-sol",
		500*time.Millisecond,
	)
	rendered := out.String()
	if !strings.Contains(rendered, "✗ round-trip FAILED") {
		t.Fatalf("expected failure marker, got %q", rendered)
	}
	if !strings.Contains(rendered, "gateway returned 401") {
		t.Fatalf("expected error detail, got %q", rendered)
	}
	if !strings.Contains(rendered, "preloop agents validate") {
		t.Fatalf("expected actionable validate hint, got %q", rendered)
	}
}

func TestFormatDeferredLiveValidationRoundTrip(t *testing.T) {
	line := formatDeferredLiveValidationRoundTrip(deferredLiveValidationResult{
		Agent: AgentConfig{Name: "Hermes"},
		Outcome: &managedLiveValidationOutcome{
			Passed:    true,
			Attempted: true,
			ValidationResult: map[string]interface{}{
				"live_validation_model_alias": "openai/gpt-5.6-sol",
			},
		},
		Duration: 2 * time.Second,
	})
	if !strings.Contains(line, "round-trip OK") || !strings.Contains(line, "Hermes") {
		t.Fatalf("unexpected deferred success line: %q", line)
	}
}

func TestRunAgentsInstallRuntimeDryRunIncludesModel(t *testing.T) {
	cmd := agentsInstallRuntimeCmd
	t.Cleanup(func() {
		_ = cmd.Flags().Set("model", "")
		_ = cmd.Flags().Set("dry-run", "false")
		_ = cmd.Flags().Set("yes", "false")
	})
	if err := cmd.Flags().Set("dry-run", "true"); err != nil {
		t.Fatalf("set dry-run: %v", err)
	}
	if err := cmd.Flags().Set("yes", "true"); err != nil {
		t.Fatalf("set yes: %v", err)
	}
	if err := cmd.Flags().Set("model", "openai/gpt-5.6-sol"); err != nil {
		t.Fatalf("set model: %v", err)
	}
	// dry-run prints to stdout; ensure the flag path does not error.
	if err := runAgentsInstallRuntime(cmd, []string{"hermes"}); err != nil {
		t.Fatalf("dry run with --model failed: %v", err)
	}
}

func TestPrintLiveValidationRoundTripResultNilOutcomeAndErr(t *testing.T) {
	var out bytes.Buffer
	printLiveValidationRoundTripResult(&out, nil, nil, "openai/gpt-5.6-sol", 0)
	rendered := out.String()
	if strings.Contains(rendered, "FAILED") || strings.Contains(rendered, "OK") {
		t.Fatalf("nil/nil should finish the line quietly, got %q", rendered)
	}
}
